import type { QueryProcedure, Router } from "fixture-procs";

// The same client, whose label states GET for the subscription (an SSE adapter).
type Inner<R> = R extends Router<infer S> ? S : R;
export type SubClientOf<R> = {
  [K in keyof R]: R[K] extends QueryProcedure<infer O>
    ? { subscribe(input?: unknown): Promise<O> }
    : SubClientOf<Inner<R[K]>>;
};
export declare function createSubClient<R extends Router>(options: { url: string }): SubClientOf<R["record"]>;
